function batteryLife(opts){
  opts=opts||{};
  var cap=Number(opts.capacity);
  var volt=opts.voltage!=null?Number(opts.voltage):3.7;
  var draw=Number(opts.draw);
  if(!isFinite(cap) || !(cap>0)) return {ok:false, reason:'电池容量无效（需 > 0）'};
  if(!isFinite(draw) || !(draw>0)) return {ok:false, reason:'工作电流无效（需 > 0）'};
  if(!isFinite(volt) || !(volt>0)) return {ok:false, reason:'电压无效（需 > 0）'};
  var eff=opts.efficiency!=null?Number(opts.efficiency):0.85;
  if(!isFinite(eff) || !(eff>0)) eff=0.85;
  if(eff>1) eff=1;
  var hours=(cap*eff)/draw;
  return {ok:true, hours:hours, wh:cap*volt/1000, days:hours/24};
}

var EXPORTS={batteryLife:batteryLife};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BatteryForgePure = EXPORTS; }
